// Fail-closed classifier for the loaded delivery state (T-02-06).
// Every input that is not an explicitly recognized, well-formed state
// classifies as REFUSED — a malformed or garbage response can never fall
// through toward the CRM node. The explicit assertion node downstream is
// the second, load-bearing gate.
const s = $input.first().json;
const malformed = (why) => [{ json: { classification: 'refused', reason: 'malformed state-load response: ' + why, review: null, delivery: null, payload: null } }];
if (s === null || typeof s !== 'object' || Array.isArray(s)) {
  return malformed('not a state object');
}
if (!('review' in s) || !('delivery' in s) || !('payload' in s)) {
  return malformed('missing review/delivery/payload contract');
}
const review = s.review;
const delivery = s.delivery;
const payload = s.payload;
if (review === null) {
  return [{ json: { classification: 'refused', reason: 'unknown review — no such review exists', review: null, delivery: null, payload: null } }];
}
if (typeof review !== 'object' || typeof review.review_id !== 'string' || typeof review.state !== 'string') {
  return malformed('review record shape invalid');
}
if (delivery !== null && (typeof delivery !== 'object' || typeof delivery.state !== 'string')) {
  return malformed('delivery record shape invalid');
}
if (delivery && delivery.state === 'committed') {
  return [{ json: { classification: 'committed', reason: 'delivery already committed — the existing effect is returned before the assertion', review, delivery, payload: null } }];
}
if (
  review.state === 'approved' &&
  review.approval &&
  review.approval.recorded === true &&
  review.approval.action === 'approve' &&
  review.approval.by === 'reviewer' &&
  delivery &&
  (delivery.state === 'pending' || delivery.state === 'retryable') &&
  payload !== null &&
  typeof payload === 'object'
) {
  return [{ json: { classification: 'candidate', reason: 'approved by a recorded reviewer action — proceeding to the explicit assertion', review, delivery, payload } }];
}
const reason = review.state === 'approved'
  ? 'approved state exists without the separately recorded reviewer approval — conflicting state refused'
  : 'review state is "' + review.state + '" — only an exactly approved review may deliver';
return [{ json: { classification: 'refused', reason, review, delivery, payload: null } }];

// LOAD-BEARING APPROVAL ASSERTION — the sole immediate predecessor of the
// CRM node (T-02-06). Throws unless EVERY recorded-state invariant holds:
// exact approved state, separately recorded reviewer approval, pending or
// retryable delivery, stable CRM idempotency key bound to this review,
// canonical payload hash recomputed IN-GRAPH, and required contact fields.
// The mock is NOT the approval gate; this node is.
const s = $input.first().json;
if (!s || typeof s !== 'object') throw new Error('assertion input malformed — CRM delivery refused');
const review = s.review;
const delivery = s.delivery;
const payload = s.payload;
if (!review || !delivery || !payload) throw new Error('assertion input incomplete — CRM delivery refused');

if (review.state !== 'approved') {
  throw new Error('review ' + review.review_id + ' is "' + review.state + '", not exactly "approved" — CRM delivery refused');
}
if (!review.approval || review.approval.recorded !== true || review.approval.action !== 'approve' || review.approval.by !== 'reviewer') {
  throw new Error('approval is not a separately recorded reviewer action — CRM delivery refused');
}
if (delivery.state !== 'pending' && delivery.state !== 'retryable') {
  throw new Error('delivery state "' + delivery.state + '" is not pending/retryable — CRM delivery refused');
}
const expectedKey = 'crmkey_' + review.review_id;
if (delivery.crm_idempotency_key !== expectedKey) {
  throw new Error('stable CRM idempotency key mismatch — CRM delivery refused');
}

// Inline SHA-256 (the pinned sandbox forbids require) over the same
// canonical JSON the demo state computes, so the graph itself proves the
// payload matches the recorded hash.
const sha256hex = (ascii) => {
  const rightRotate = (value, amount) => (value >>> amount) | (value << (32 - amount));
  const maxWord = Math.pow(2, 32);
  let result = '';
  const words = [];
  const asciiBitLength = ascii.length * 8;
  let hash = sha256hex.h = sha256hex.h || [];
  const k = sha256hex.k = sha256hex.k || [];
  let primeCounter = k.length;
  const isComposite = {};
  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (let i = 0; i < 313; i += candidate) isComposite[i] = candidate;
      hash[primeCounter] = (Math.pow(candidate, 0.5) * maxWord) | 0;
      k[primeCounter++] = (Math.pow(candidate, 1 / 3) * maxWord) | 0;
    }
  }
  ascii += '\x80';
  while (ascii.length % 64 - 56) ascii += '\x00';
  for (let i = 0; i < ascii.length; i++) {
    const j = ascii.charCodeAt(i);
    if (j >> 8) return null;
    words[i >> 2] |= j << (((3 - i) % 4) * 8);
  }
  words[words.length] = (asciiBitLength / maxWord) | 0;
  words[words.length] = asciiBitLength;
  for (let j = 0; j < words.length;) {
    const w = words.slice(j, j += 16);
    const oldHash = hash;
    hash = hash.slice(0, 8);
    for (let i = 0; i < 64; i++) {
      const w15 = w[i - 15];
      const w2 = w[i - 2];
      const a = hash[0];
      const e = hash[4];
      const temp1 = hash[7]
        + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25))
        + ((e & hash[5]) ^ (~e & hash[6]))
        + k[i]
        + (w[i] = i < 16 ? w[i] : (
          w[i - 16]
          + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3))
          + w[i - 7]
          + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))
        ) | 0);
      const temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22))
        + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
      hash = [(temp1 + temp2) | 0].concat(hash);
      hash[4] = (hash[4] + temp1) | 0;
    }
    for (let i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
  }
  for (let i = 0; i < 8; i++) {
    for (let j = 3; j + 1; j--) {
      const b = (hash[i] >> (j * 8)) & 255;
      result += (b < 16 ? '0' : '') + b.toString(16);
    }
  }
  return result;
};
const canonical = (v) => Array.isArray(v)
  ? '[' + v.map(canonical).join(',') + ']'
  : (v !== null && typeof v === 'object')
    ? '{' + Object.keys(v).sort().map((key) => JSON.stringify(key) + ':' + canonical(v[key])).join(',') + '}'
    : JSON.stringify(v ?? null);
const canonicalString = canonical({
  contact: payload.contact ?? null,
  case_info: payload.case_info ?? null,
  source: payload.source ?? null,
  referral_source: payload.referral_source ?? null,
  firm: payload.firm ?? null,
  timestamp: payload.timestamp ?? null,
});
const recomputedHash = sha256hex(unescape(encodeURIComponent(canonicalString)));
if (recomputedHash === null || recomputedHash !== delivery.payload_hash) {
  throw new Error('payload hash mismatch — the stored record does not match this payload; CRM delivery refused');
}

if (!payload.contact || typeof payload.contact !== 'object') throw new Error('contact payload missing — CRM delivery refused');
if (!payload.contact.first_name || !payload.contact.last_name) throw new Error('contact name fields missing — CRM delivery refused');
if (!payload.contact.email && !payload.contact.phone) throw new Error('no contact email or phone — CRM delivery refused');

// Only CRM-bound fields cross this boundary.
return [{ json: {
  idempotency_key: expectedKey,
  ...(payload.contact.email ? { email: payload.contact.email } : {}),
  ...(payload.contact.phone ? { phone: payload.contact.phone } : {}),
  review_id: review.review_id
} }];

// Interpret the counted CRM boundary's response. Fail closed on shape:
// ONLY an explicit committed/exists effect is a delivery. The deterministic
// pre-commit fault (a TRANSPORT SUCCESS carrying an application failure:
// committed:false, retryable:true, fault_injected:true) routes to a truthful
// retryable outcome — never a 'delivered' claim. Anything unrecognized is a
// non-delivery.
const body = $input.first().json;
const isObject = body !== null && typeof body === 'object' && !Array.isArray(body);
if (isObject && (body.status === 'committed' || body.status === 'exists') && body.effect && typeof body.effect.effect_id === 'string') {
  return [{ json: { outcome: 'delivered', review_id: body.review_id ?? null, effect_id: body.effect.effect_id, crm_idempotency_key: body.effect.key ?? null } }];
}
if (isObject && body.fault_injected === true && body.committed === false && body.retryable === true) {
  return [{ json: { outcome: 'crm_failed_retryable', review_id: body.review_id ?? null, committed: false, retryable: true } }];
}
return [{ json: { outcome: 'crm_failed_retryable', review_id: isObject && typeof body.review_id === 'string' ? body.review_id : null, committed: false, retryable: true, unrecognized: true } }];
